class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        # Ensure nums1 is the smaller array
        if len(nums1) > len(nums2):
            nums1, nums2 = nums2, nums1

        m, n = len(nums1), len(nums2)
        total_left = (m + n + 1) // 2
        left, right = 0, m
        odd = (m + n) & 1

        while left <= right:
            i = (left + right) >> 1
            j = total_left - i

            if i > 0 and nums1[i - 1] > nums2[j]:
                right = i - 1
            elif i < m and nums2[j - 1] > nums1[i]:
                left = i + 1
            else:
                if i == 0:
                    max_left = nums2[j - 1]
                elif j == 0:
                    max_left = nums1[i - 1]
                else:
                    max_left = nums1[i - 1] if nums1[i - 1] > nums2[j - 1] else nums2[j - 1]

                if odd:
                    return float(max_left)

                if i == m:
                    min_right = nums2[j]
                elif j == n:
                    min_right = nums1[i]
                else:
                    min_right = nums1[i] if nums1[i] < nums2[j] else nums2[j]

                return (max_left + min_right) / 2.0

class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        m, n = len(s), len(p)
        prev = [False] * (n + 1)
        prev[0] = True

        # Initialize first row for patterns like a*, a*b*, .*
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                prev[j] = prev[j - 2]

        for i in range(1, m + 1):
            curr = [False] * (n + 1)
            si = s[i - 1]
            for j in range(1, n + 1):
                pj = p[j - 1]
                if pj == '.' or pj == si:
                    curr[j] = prev[j - 1]
                elif pj == '*':
                    # Zero occurrences of preceding element
                    curr[j] = curr[j - 2]
                    # One or more occurrences if preceding matches current char
                    if p[j - 2] == '.' or p[j - 2] == si:
                        curr[j] = curr[j] or prev[j]
            prev = curr

        return prev[n]

