class Solution:
    def maxArea(self, height: List[int]) -> int:
        left, right = 0, len(height) - 1
        max_water = 0

        while left < right:
            hl = height[left]
            hr = height[right]
            if hl < hr:
                area = (right - left) * hl
                left += 1
            else:
                area = (right - left) * hr
                right -= 1
            if area > max_water:
                max_water = area

        return max_water

