class Solution:
    def combinationSum2(self, candidates, target):
        candidates.sort()
        result = []
        path = []

        def backtrack(start, remaining):
            if remaining == 0:
                result.append(path[:])
                return

            for i in range(start, len(candidates)):
                c = candidates[i]
                if c > remaining:
                    break
                if i > start and c == candidates[i - 1]:
                    continue
                path.append(c)
                backtrack(i + 1, remaining - c)
                path.pop()

        backtrack(0, target)
        return result

class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        # Use two rows for DP to reduce memory from O(m*n) to O(n)
        prev = [False] * (len(p) + 1)
        curr = [False] * (len(p) + 1)

        # Empty string matches empty pattern
        prev[0] = True

        # Handle patterns like "*", "**", "*a*", etc. for empty string
        for j in range(1, len(p) + 1):
            if p[j - 1] == '*':
                prev[j] = prev[j - 1]

        # Fill the DP table
        for i in range(1, len(s) + 1):
            curr[0] = False  # Non-empty string cannot match empty pattern
            for j in range(1, len(p) + 1):
                if p[j - 1] == '*':
                    # '*' matches empty sequence (curr[j-1])
                    # or '*' matches one or more characters (prev[j])
                    curr[j] = curr[j - 1] or prev[j]
                elif p[j - 1] == '?' or p[j - 1] == s[i - 1]:
                    # '?' matches any single character
                    # or exact character match
                    curr[j] = prev[j - 1]
                else:
                    curr[j] = False
            # Swap rows
            prev, curr = curr, prev

        return prev[len(p)]

class Solution:
    def totalNQueens(self, n: int) -> int:
        # Use bitmasks instead of boolean arrays for faster checks and updates
        def backtrack(row: int, cols: int, diag1: int, diag2: int) -> int:
            if row == n:
                return 1
            count = 0
            # Available columns in this row
            available = (~(cols | diag1 | diag2)) & ((1 << n) - 1)
            while available:
                # Pick the least significant available column
                bit = available & -available
                available ^= bit
                count += backtrack(
                    row + 1,
                    cols | bit,
                    (diag1 | bit) << 1,
                    (diag2 | bit) >> 1
                )
            return count

        return backtrack(0, 0, 0, 0)

class Solution:
    def canJump(self, nums):
        last = len(nums) - 1
        max_reach = 0
        for i in range(last):
            if i > max_reach:
                return False
            reach = i + nums[i]
            if reach > max_reach:
                max_reach = reach
                if max_reach >= last:
                    return True
        return max_reach >= last

class Solution:
    def merge(self, intervals):
        if not intervals:
            return []

        intervals.sort(key=lambda x: x[0])

        merged = []
        start, end = intervals[0]

        for s, e in intervals[1:]:
            if s <= end:
                if e > end:
                    end = e
            else:
                merged.append([start, end])
                start, end = s, e

        merged.append([start, end])
