class Solution:
    def uniquePaths(self, m: int, n: int) -> int:
        # Use combinatorics: C(m+n-2, min(m,n)-1)
        # Ensure we use the smaller number of steps for fewer multiplications
        N = m + n - 2
        K = min(m, n) - 1
        result = 1
        for i in range(1, K + 1):
            result = result * (N - K + i) // i
        return result

class Solution:
    def uniquePathsWithObstacles(self, obstacleGrid):
        m, n = len(obstacleGrid), len(obstacleGrid[0])

        if obstacleGrid[0][0] == 1 or obstacleGrid[m-1][n-1] == 1:
            return 0

        dp = [0] * n
        dp[0] = 1

        for i in range(m):
            for j in range(n):
                if obstacleGrid[i][j] == 1:
                    dp[j] = 0
                elif j > 0:
                    dp[j] += dp[j-1]

        return dp[n-1]

