class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        m, n = len(word1), len(word2)

        # Ensure word1 is the shorter string to minimize memory usage
        if m > n:
            word1, word2 = word2, word1
            m, n = n, m

        # Use a single list for dynamic programming
        dp = list(range(n + 1))

        for i in range(1, m + 1):
            prev = dp[0]
            dp[0] = i
            char1 = word1[i - 1]
            for j in range(1, n + 1):
                temp = dp[j]
                if char1 == word2[j - 1]:
                    dp[j] = prev
                else:
                    # Inline min calculation to avoid function call overhead
                    delete = dp[j] + 1
                    insert = dp[j - 1] + 1
                    replace = prev + 1
                    if delete < insert:
                        dp[j] = delete if delete < replace else replace
                    else:
                        dp[j] = insert if insert < replace else replace
                prev = temp

        return dp[n]

