class Solution:
    def maximalRectangle(self, matrix: List[List[str]]) -> int:
        if not matrix or not matrix[0]:
            return 0

        cols = len(matrix[0])
        heights = [0] * cols
        max_area = 0

        for row in matrix:
            for i in range(cols):
                heights[i] = heights[i] + 1 if row[i] == '1' else 0

            # Inline largest rectangle in histogram calculation
            stack = []
            # Use a local variable for heights to avoid attribute lookups
            h = heights
            # Process histogram with sentinel logic without modifying the list
            for i in range(cols + 1):
                current = h[i] if i < cols else 0
                while stack and h[stack[-1]] > current:
                    height = h[stack.pop()]
                    width = i if not stack else i - stack[-1] - 1
                    area = height * width
                    if area > max_area:
                        max_area = area
                stack.append(i)

        return max_area

class Solution:
    def isScramble(self, s1: str, s2: str) -> bool:
        from functools import lru_cache

        @lru_cache(None)
        def dfs(a: str, b: str) -> bool:
            if a == b:
                return True
            if len(a) != len(b) or sorted(a) != sorted(b):
                return False
            n = len(a)
            for i in range(1, n):
                if (dfs(a[:i], b[:i]) and dfs(a[i:], b[i:])) or \
                   (dfs(a[:i], b[-i:]) and dfs(a[i:], b[:-i])):
                    return True
            return False

        return dfs(s1, s2)

