class TreeNode:
    __slots__ = ("val", "left", "right")

    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

    @staticmethod
    def deserialize(data):
        """Deserializes a list to a binary tree (level-order)."""
        if not data:
            return None
        nodes = [None if val is None else TreeNode(val) for val in data]
        kids = nodes[::-1]
        root = kids.pop()
        for node in nodes:
            if node:
                if kids:
                    node.left = kids.pop()
                if kids:
                    node.right = kids.pop()
        return root


class Solution:
    def isBalanced(self, root: TreeNode) -> bool:
        def check(node):
            if node is None:
                return 0
            left_height = check(node.left)
            if left_height == -1:
                return -1
            right_height = check(node.right)
            if right_height == -1 or abs(left_height - right_height) > 1:
                return -1
            return (left_height if left_height > right_height else right_height) + 1

        return check(root) != -1

