class Solution:
    def partition(self, s: str):
        def is_palindrome(sub):
            return sub == sub[::-1]

        def backtrack(start, path):
            if start == len(s):
                result.append(path[:])
                return
            for end in range(start + 1, len(s) + 1):
                if is_palindrome(s[start:end]):
                    path.append(s[start:end])
                    backtrack(end, path)
                    path.pop()

        result = []
        backtrack(0, [])
        return result

class Solution:
    def minCut(self, s: str) -> int:
        n = len(s)
        dp = [0] * n
        is_pal = [True] * n

        for i in range(n - 1, -1, -1):
            prev = True
            for j in range(i, n):
                curr = (s[i] == s[j]) and (j - i <= 2 or prev)
                prev = is_pal[j]
                is_pal[j] = curr

        for i in range(n):
            if is_pal[i]:
                dp[i] = 0
            else:
                dp[i] = i
                for j in range(i):
                    if is_pal[j + 1]:
                        dp[i] = min(dp[i], dp[j] + 1)

        return dp[-1]

