class Solution:
    def candy(self, ratings: List[int]) -> int:
        n = len(ratings)
        candies = [1] * n

        # Left to right pass
        prev = 1
        for i in range(1, n):
            if ratings[i] > ratings[i - 1]:
                prev += 1
                candies[i] = prev
            else:
                prev = 1

        # Right to left pass
        total = candies[-1]
        prev = 1
        for i in range(n - 2, -1, -1):
            if ratings[i] > ratings[i + 1]:
                prev += 1
                if prev > candies[i]:
                    candies[i] = prev
            else:
                prev = 1
            total += candies[i]

        return total

