        left = 0
        max_len = 0
        last_pos = {}
        distinct = 0

        for right, ch in enumerate(s):
            if ch not in last_pos or last_pos[ch] < left:
                distinct += 1
                while distinct > 2:
                    oldest_char = min(last_pos, key=last_pos.get)
                    left = last_pos[oldest_char] + 1
                    del last_pos[oldest_char]
                    distinct -= 1
            last_pos[ch] = right
            max_len = max(max_len, right - left + 1)

