class Solution:
    def maxProfit(self, k: int, prices: list[int]) -> int:
        n = len(prices)
        if n == 0 or k == 0:
            return 0

        # If k is large enough, it's the same as unlimited transactions
        if k >= n // 2:
            profit = 0
            for i in range(1, n):
                if prices[i] > prices[i - 1]:
                    profit += prices[i] - prices[i - 1]
            return profit

        # Use two 1D arrays instead of a 2D table to save memory
        prev = [0] * n
        curr = [0] * n

        for _ in range(1, k + 1):
            max_diff = -prices[0]
            for d in range(1, n):
                curr[d] = max(curr[d - 1], prices[d] + max_diff)
                max_diff = max(max_diff, prev[d] - prices[d])
            prev, curr = curr, prev

        return prev[n - 1]

