class Solution:
    def countDigitOne(self, n: int) -> int:
        count = 0
        factor = 1

        while factor <= n:
            higher, remainder = divmod(n, factor * 10)
            current, lower = divmod(remainder, factor)

            if current == 0:
                count += higher * factor
            elif current == 1:
                count += higher * factor + lower + 1
            else:
                count += (higher + 1) * factor

            factor *= 10

        return count

class Solution:
    def isAnagram(self, s: str, t: str) -> bool:
        if len(s) != len(t):
            return False

        count = [0] * 26
        base = 97

        for char in s:
            count[ord(char) - base] += 1

        for char in t:
            idx = ord(char) - base
            count[idx] -= 1
            if count[idx] < 0:
                return False

        return True

class Solution:
    def isStrobogrammatic(self, num: str) -> bool:
        strob_map = {
            '0': '0',
            '1': '1',
            '6': '9',
            '8': '8',
            '9': '6'
        }

        left, right = 0, len(num) - 1
        while left <= right:
            if num[left] not in strob_map or strob_map[num[left]] != num[right]:
                return False
            left += 1
            right -= 1

        return True
